import React from "react";
import { Link } from "react-router-dom";

// import axios from "axios";

import GeneralContext from "./GeneralContext";

import "./BuyActionWindow.css";

const BuyActionWindow = ({ uid }) => {
  const handleCancelClick = () => {
    GeneralContext.closeBuyWindow();
  };
  const handleBuyClick = () => {
    console.log("Buy button clicked for:", uid);
    // Yahan aap apna order place karne ka logic likh sakte hain
    GeneralContext.closeBuyWindow(); // Buy karne ke baad window band karne ke liye
  };

  return (
    <div className="container" id="buy-window" draggable="true">
      <div className="regular-order">
        <div className="inputs">
          <fieldset>
            <legend>Qty.</legend>
            <input
              type="number"
              name="qty"
              id="qty"
            //   onChange={(e) => setStockQuantity(e.target.value)}
            //   value={stockQuantity}
            />
          </fieldset>
          <fieldset>
            <legend>Price</legend>
            <input
              type="number"
              name="price"
              id="price"
              step="0.05"
            //   onChange={(e) => setStockPrice(e.target.value)}
            //   value={stockPrice}
            />
          </fieldset>
        </div>
      </div>

      <div className="buttons">
        <span>Margin required ₹140.65</span>
        <div>
          <button className="btn btn-blue" onClick={handleBuyClick}>
            Buy
          </button>
          <button to="" className="btn btn-grey" onClick={handleCancelClick}>
            Cancel
          </button>
        </div>
      </div>
    </div>
  );
};

export default BuyActionWindow;
